<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Employee Documents · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,'employee-documents',$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><header class="page-header"><div><p class="eyebrow">RESTRICTED WORKFORCE FILES</p><h1>Employee documents</h1><p>Private PDF and image files available only through authorized Atlas downloads.</p></div><form method="get"><input type="hidden" name="route" value="employee-documents"><select name="membership_id" onchange="this.form.submit()"><?php foreach($data['people'] as $person):?><option value="<?=$person['membership_id']?>" <?=$person['membership_id']===$selectedEmployeeId?'selected':''?>><?=esc($person['name'])?></option><?php endforeach;?></select></form></header><?php if($notice):?><div class="page-flash <?=$notice['type']?>"><span>✓</span><?=esc($notice['message'])?></div><?php endif;?><section class="planning-grid"><article class="panel"><h2>Upload for <?=esc($employeeWorkspace['profile']['name'])?></h2><form method="post" enctype="multipart/form-data" class="stack-form"><?=Csrf::field()?><input type="hidden" name="action" value="upload_employee_document"><input type="hidden" name="membership_id" value="<?=$selectedEmployeeId?>"><label>PDF, JPG, or PNG up to 10 MB<input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png" required></label><button class="button primary">Upload securely</button></form></article><article class="panel"><h2>Stored documents</h2><?php foreach($workforceAdmin['documents'] as $document):?><div class="planning-row"><span><strong><?=esc($document['document_name'])?></strong><small><?=esc($document['uploaded_by_name'].' · '.$document['created_at'].' · '.round($document['file_size']/1024).' KB')?></small></span><a class="button secondary" 